    @Test
    public void testAvailable_whenNotAtEOF_returns1() throws IOException {
        when(inputStreamMock.read(singleByte)).thenReturn(1);
        when(baseNCodecMock.eof).thenReturn(false);

        int result = testInstance.available();

        verify(inputStreamMock, times(1)).read(singleByte);
